package dev.jackteng.figura;
import com.fasterxml.jackson.databind.*;
import dev.jackteng.figura.dto.AccessPayloads.*;
import dev.jackteng.figura.pojo.CustomUserDetails;
import dev.jackteng.figura.service.StaffAccessService;
import jakarta.servlet.http.Cookie;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.autoconfigure.web.servlet.*;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.data.redis.core.StringRedisTemplate;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder;
import org.springframework.test.context.ActiveProfiles;
import org.springframework.test.web.servlet.*;
import org.springframework.web.server.ResponseStatusException;
import java.util.*;
import java.util.concurrent.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;

@SpringBootTest @AutoConfigureMockMvc(print=MockMvcPrint.NONE) @ActiveProfiles("demo")
@EnabledIfEnvironmentVariable(named="SHOP_MYSQL_INTEGRATION",matches="true")
class StaffAccessIntegrationTest {
 @Autowired MockMvc mvc; @Autowired ObjectMapper json; @org.springframework.boot.test.mock.mockito.SpyBean JdbcTemplate db;
 @Autowired dev.jackteng.figura.service.CatalogService catalog; @Autowired StaffAccessService access; @Autowired BCryptPasswordEncoder passwords; @Autowired StringRedisTemplate redis;
 private final Set<Integer> users=new HashSet<>(),roles=new HashSet<>();private final Set<String> sessions=new HashSet<>();
 record Client(String csrf,List<Cookie> cookies,int id) {}
 JsonNode data(MvcResult r)throws Exception{return json.readTree(r.getResponse().getContentAsString(java.nio.charset.StandardCharsets.UTF_8)).path("data");}
 Cookie cookie(MvcResult r,String name){String h=r.getResponse().getHeaders("Set-Cookie").stream().filter(v->v.startsWith(name+"=")).findFirst().orElseThrow();return new Cookie(name,h.split(";",2)[0].substring(name.length()+1));}
 MvcResult call(Client c,String method,String path,Object body)throws Exception{var b=request(org.springframework.http.HttpMethod.valueOf(method),"/figura/api"+path).contextPath("/figura").servletPath("/api"+path.split("\\?",2)[0]);if(c!=null){b.cookie(c.cookies().toArray(Cookie[]::new));if(!method.equals("GET"))b.header("X-XSRF-TOKEN",c.csrf());}if(body!=null)b.contentType("application/json").content(json.writeValueAsBytes(body));return mvc.perform(b).andReturn();}
 Client login(String name,String password)throws Exception{var r=call(null,"GET","/auth/csrf",null);var g=new Client(data(r).path("token").asText(),List.of(cookie(r,"XSRF-TOKEN")),0);String device=UUID.randomUUID().toString();r=mvc.perform(post("/figura/api/admin/login").contextPath("/figura").servletPath("/api/admin/login").cookie(g.cookies().get(0)).header("X-XSRF-TOKEN",g.csrf()).param("username",name).param("password",password).param("deviceId",device)).andReturn();assertEquals(200,r.getResponse().getStatus());int id=data(r).path("id").asInt();sessions.add("shop:session:"+id+":"+device);return new Client(g.csrf(),List.of(g.cookies().get(0),cookie(r,"accessToken"),cookie(r,"refreshToken")),id);}
 Client admin()throws Exception{return login("shop_admin",System.getenv("DEMO_ADMIN_PASSWORD"));}
 String uuid(){return UUID.randomUUID().toString();}
 String password(){return System.getenv("DEMO_STAFF_PASSWORD");}
 Map<String,Object> createBody(List<Integer> rs){return new HashMap<>(Map.of("username","rbac_"+UUID.randomUUID().toString().replace("-",""),"password",password(),"enabled",true,"roleIds",rs,"requestId",uuid(),"note","建立測試員工"));}
 JsonNode create(Client a,List<Integer> rs)throws Exception{var r=call(a,"POST","/admin/access/staff",createBody(rs));assertEquals(201,r.getResponse().getStatus());int id=data(r).path("event").path("targetId").asInt();users.add(id);return json.readTree(data(r).path("event").path("afterState").asText());}
 List<Integer> ints(JsonNode n){var out=new ArrayList<Integer>();n.forEach(x->out.add(x.asInt()));return out;}
 Map<String,Object> staffWrite(JsonNode u,boolean enabled,List<Integer> rs){return new HashMap<>(Map.of("enabled",enabled,"roleIds",rs,"expectedVersion",u.path("version").asInt(),"requestId",uuid(),"note","調整測試授權"));}
 List<Integer> caps(){return access.permissions().stream().map(Capability::id).toList();}
 int roleFixture(Client a,List<Integer> ps)throws Exception{var r=call(a,"POST","/admin/access/roles",Map.of("name","測試角色 "+uuid(),"description","安全測試","enabled",true,"permissionIds",ps,"expectedVersion",0,"requestId",uuid(),"note","建立測試角色"));assertEquals(201,r.getResponse().getStatus());int id=data(r).path("event").path("targetId").asInt();roles.add(id);return id;}
 JsonNode after(MvcResult r)throws Exception{return json.readTree(data(r).path("event").path("afterState").asText());}
 @AfterEach void cleanup(){for(int id:users)db.update("UPDATE user SET is_stop='T',auth_version=auth_version+1 WHERE id=?",id);for(int id:roles)db.update("UPDATE role SET enabled=FALSE WHERE id=?",id);if(!sessions.isEmpty())redis.delete(sessions);}
 @Test void createReplayHasSafeProjectionAndPasswordHash()throws Exception{var a=admin();var input=createBody(List.of(2));var r=call(a,"POST","/admin/access/staff",input);assertEquals(201,r.getResponse().getStatus());var u=after(r);users.add(u.path("id").asInt());assertEquals(db.queryForObject("SELECT created_at FROM staff_access_event WHERE request_id=?",(row,n)->row.getObject(1,java.time.LocalDateTime.class),input.get("requestId")),java.time.LocalDateTime.parse(data(r).path("event").path("createdAt").asText()));assertFalse(u.has("password"));assertFalse(u.has("authVersion"));assertFalse(data(r).path("event").has("fingerprint"));assertFalse(r.getResponse().getContentAsString(java.nio.charset.StandardCharsets.UTF_8).contains(password()));assertTrue(passwords.matches(password(),db.queryForObject("SELECT password FROM user WHERE id=?",String.class,u.path("id").asInt())));assertEquals(200,call(a,"POST","/admin/access/staff",input).getResponse().getStatus());input.put("password",password()+"x");assertEquals(409,call(a,"POST","/admin/access/staff",input).getResponse().getStatus());assertEquals(1,db.queryForObject("SELECT COUNT(*) FROM staff_access_event WHERE request_id=?",Integer.class,input.get("requestId")));}
 @Test void rosterPermissionsAuditAndPaginationAreReadOnly()throws Exception{var a=admin();var u=create(a,List.of(2));assertEquals(200,call(a,"GET","/admin/access/staff",null).getResponse().getStatus());assertEquals(400,call(a,"GET","/admin/access/staff?pageSize=51",null).getResponse().getStatus());assertEquals(400,call(a,"GET","/admin/access/audit?page=0",null).getResponse().getStatus());var catalog=data(call(a,"GET","/admin/access/permissions",null));assertTrue(catalog.size()>20);assertFalse(catalog.get(0).has("url"));assertEquals(403,call(a,"DELETE","/admin/access/audit",Map.of()).getResponse().getStatus());assertTrue(data(call(a,"GET","/admin/access/audit",null)).path("total").asInt()>0);}
 @Test void csrfAudienceAndLegacyMutatorsFailClosed()throws Exception{var a=admin();var s=login("shop_staff",password());assertEquals(403,call(s,"GET","/admin/access/staff",null).getResponse().getStatus());assertEquals(401,call(null,"GET","/admin/access/roles",null).getResponse().getStatus());assertEquals(403,call(new Client("wrong",a.cookies(),a.id()),"POST","/admin/access/staff",createBody(List.of(2))).getResponse().getStatus());for(String p:List.of("/admin/register","/admin/stopAccount","/admin/user/update","/role/assignUser","/role/assignPermission"))assertEquals(410,call(a,"POST",p,Map.of()).getResponse().getStatus());}
 @Test void unknownFieldsInvalidRolesDuplicatesAndUtf8PasswordsRejected()throws Exception{var a=admin();for(String field:List.of("actorId","id","isStop","url","method")){var b=createBody(List.of(2));b.put(field,"spoof");assertEquals(400,call(a,"POST","/admin/access/staff",b).getResponse().getStatus());}assertEquals(400,call(a,"POST","/admin/access/staff",createBody(List.of(2,2))).getResponse().getStatus());assertEquals(404,call(a,"POST","/admin/access/staff",createBody(List.of(999999))).getResponse().getStatus());var b=createBody(List.of(2));b.put("password","密".repeat(30));assertEquals(400,call(a,"POST","/admin/access/staff",b).getResponse().getStatus());}
 @Test void disableReenableNeverRevivesAccessOrRefresh()throws Exception{var a=admin();var u=create(a,List.of(2));var c=login(u.path("username").asText(),password());int id=u.path("id").asInt();var r=call(a,"PUT","/admin/access/staff/"+id,staffWrite(u,false,List.of(2)));assertEquals(201,r.getResponse().getStatus());assertEquals(401,call(c,"GET","/auth/me",null).getResponse().getStatus());u=after(r);assertEquals(201,call(a,"PUT","/admin/access/staff/"+id,staffWrite(u,true,List.of(2))).getResponse().getStatus());assertEquals(401,call(c,"GET","/auth/me",null).getResponse().getStatus());assertEquals(401,call(c,"POST","/auth/refresh",null).getResponse().getStatus());assertEquals(200,call(login(u.path("username").asText(),password()),"GET","/auth/me",null).getResponse().getStatus());}
 @Test void staleWritesAndUuidCrossTargetRollBack()throws Exception{var a=admin();var u=create(a,List.of(2));var other=create(a,List.of(2));var b=staffWrite(u,false,List.of(2));String path="/admin/access/staff/"+u.path("id").asInt();assertEquals(201,call(a,"PUT",path,b).getResponse().getStatus());assertEquals(200,call(a,"PUT",path,b).getResponse().getStatus());b.put("requestId",uuid());assertEquals(409,call(a,"PUT",path,b).getResponse().getStatus());b.put("requestId",data(call(a,"GET","/admin/access/audit",null)).path("items").get(0).path("requestId").asText());assertEquals(409,call(a,"PUT","/admin/access/staff/"+other.path("id").asInt(),b).getResponse().getStatus());assertEquals("F",db.queryForObject("SELECT is_stop FROM user WHERE id=?",String.class,other.path("id").asInt()));}
 @Test void partialGovernanceWriterCannotEscalate()throws Exception{var a=admin();int r=roleFixture(a,List.of(1,100,102));var u=create(a,List.of(r));var c=login(u.path("username").asText(),password());assertEquals(200,call(c,"GET","/admin/access/staff",null).getResponse().getStatus());assertEquals(403,call(c,"PUT","/admin/access/staff/"+u.path("id").asInt(),staffWrite(u,true,List.of(1))).getResponse().getStatus());}
 @Test void lastManagerCannotDisableSelfOrRemoveOwnRole()throws Exception{var a=admin();var self=access.staffList(1,50).items().stream().filter(u->u.id()==a.id()).findFirst().orElseThrow();for(boolean enabled:List.of(false,true)){var b=new StaffWrite(enabled,List.of(2),self.version(),uuid(),"最後管理員測試");assertThrows(ResponseStatusException.class,()->access.updateStaff(a.id(),b,new CustomUserDetails("spoof",a.id(),List.of())));}assertEquals(self,access.staffList(1,50).items().stream().filter(u->u.id()==a.id()).findFirst().orElseThrow());}
 @Test void removingLastManagerCapabilitiesIsAtomic()throws Exception{var a=admin();var r=access.roles(1,50).items().stream().filter(x->x.id()==1).findFirst().orElseThrow();var b=new RoleWrite(r.name(),r.description(),true,List.of(1),r.version(),uuid(),"移除最後管理權限");assertEquals(409,call(a,"PUT","/admin/access/roles/1",b).getResponse().getStatus());assertEquals(r,access.roles(1,50).items().stream().filter(x->x.id()==1).findFirst().orElseThrow());}
 @Test void roleSecurityChangeRevokesSessionsButMetadataEditDoesNot()throws Exception{var a=admin();int id=roleFixture(a,List.of(1,10));var u=create(a,List.of(id));var c=login(u.path("username").asText(),password());var role=access.roles(1,50).items().stream().filter(r->r.id()==id).findFirst().orElseThrow();var body=new RoleWrite("新名稱",role.description(),true,role.permissionIds(),role.version(),uuid(),"改名稱");assertEquals(201,call(a,"PUT","/admin/access/roles/"+id,body).getResponse().getStatus());assertEquals(200,call(c,"GET","/auth/me",null).getResponse().getStatus());body=new RoleWrite("新名稱",role.description(),false,role.permissionIds(),role.version()+1,uuid(),"停用角色");assertEquals(201,call(a,"PUT","/admin/access/roles/"+id,body).getResponse().getStatus());assertEquals(401,call(c,"GET","/auth/me",null).getResponse().getStatus());assertEquals(400,call(a,"PUT","/admin/access/roles/"+id,new RoleWrite("x","",true,List.of(99999),role.version()+2,uuid(),"非法權限")).getResponse().getStatus());}
 @Test void catalogWritesRecheckLiveGrantsInsideTransaction()throws Exception{
  var a=admin();int id=roleFixture(a,List.of(1,10));var u=create(a,List.of(id));var actor=new CustomUserDetails("spoof",u.path("id").asInt(),List.of());
  String title="RBAC catalog "+uuid();var input=new dev.jackteng.figura.dto.CatalogPayloads.Write(title,"ELPSY","公仔","安全測試",0,List.of(new dev.jackteng.figura.dto.CatalogPayloads.Sku(null,"RBAC-"+uuid(),"標準款",100,true)));
  assertThrows(ResponseStatusException.class,()->catalog.create(input,actor));assertEquals(0,db.queryForObject("SELECT COUNT(*) FROM catalog_product WHERE title=?",Integer.class,title));
  var role=access.roles(1,50).items().stream().filter(r->r.id()==id).findFirst().orElseThrow();access.saveRole(id,new RoleWrite(role.name(),role.description(),true,List.of(1,10,12),role.version(),uuid(),"授予商品建立"),new CustomUserDetails("spoof",a.id(),List.of()));
  var product=catalog.create(input,actor);
  try{access.saveRole(id,new RoleWrite(role.name(),role.description(),false,List.of(1,10,12),role.version()+1,uuid(),"停用角色"),new CustomUserDetails("spoof",a.id(),List.of()));assertThrows(ResponseStatusException.class,()->catalog.create(input,actor));assertEquals(1,db.queryForObject("SELECT COUNT(*) FROM catalog_product WHERE title=?",Integer.class,title));}
  finally{db.update("UPDATE catalog_product SET status='ARCHIVED' WHERE id=?",product.id());}
 }
 @Test void auditInsertionFailureRollsBackStaffAndGrants()throws Exception{var a=admin();var u=create(a,List.of(2));org.mockito.Mockito.doThrow(new org.springframework.dao.DataAccessResourceFailureException("test audit failure")).when(db).update(org.mockito.ArgumentMatchers.startsWith("INSERT INTO staff_access_event"),org.mockito.ArgumentMatchers.any(Object[].class));try{assertEquals(500,call(a,"PUT","/admin/access/staff/"+u.path("id").asInt(),staffWrite(u,false,List.of(1))).getResponse().getStatus());assertEquals("F",db.queryForObject("SELECT is_stop FROM user WHERE id=?",String.class,u.path("id").asInt()));assertEquals(0,db.queryForObject("SELECT access_version FROM user WHERE id=?",Integer.class,u.path("id").asInt()));assertEquals(List.of(2),db.queryForList("SELECT role_id FROM user_role WHERE user_id=?",Integer.class,u.path("id").asInt()));}finally{org.mockito.Mockito.reset(db);}}
 @Test void concurrentLastManagersCannotBothDisableThemselves()throws Exception{var a=admin();int role=roleFixture(a,caps());var u=create(a,List.of(role));var v=create(a,List.of(role));db.update("UPDATE user SET is_stop='T' WHERE id=?",a.id());var executor=Executors.newFixedThreadPool(2);try{var gate=new CountDownLatch(1);List<Future<Integer>> results=new ArrayList<>();for(var row:List.of(u,v)){int id=row.path("id").asInt();results.add(executor.submit(()->{gate.await();try{access.updateStaff(id,new StaffWrite(false,List.of(role),0,uuid(),"競爭停用"),new CustomUserDetails("spoof",id,List.of()));return 201;}catch(ResponseStatusException e){return e.getStatusCode().value();}}));}gate.countDown();var statuses=List.of(results.get(0).get(15,TimeUnit.SECONDS),results.get(1).get(15,TimeUnit.SECONDS));assertEquals(1,statuses.stream().filter(x->x==201).count());assertEquals(1,statuses.stream().filter(x->x==409).count());}finally{db.update("UPDATE user SET is_stop='F' WHERE id=?",a.id());executor.shutdownNow();}}
}
